def parse_duration(s: str) -> int:
    """
    Convert a duration string like '1h30m15s', '45s', '2h', '3m', '1h1s' into total seconds.
    Units appear in h, m, s order. Units may be omitted.
    """
    total_seconds = 0
    current_number = ""

    for char in s:
        if char.isdigit():
            current_number += char
        elif char == 'h':
            if current_number:
                total_seconds += int(current_number) * 3600
                current_number = ""
        elif char == 'm':
            if current_number:
                total_seconds += int(current_number) * 60
                current_number = ""
        elif char == 's':
            if current_number:
                total_seconds += int(current_number)
                current_number = ""

    # Handle any remaining number (shouldn't happen with valid input, but just in case)
    if current_number:
        total_seconds += int(current_number)

    return total_seconds
